import{_ as n,C as l,o as s,c as d,j as t,a as e,E as r,a3 as i}from"./chunks/framework.CZBGEXos.js";const f=JSON.parse('{"title":"Alerts","description":"","frontmatter":{},"headers":[],"relativePath":"ru/tools/alerts.md","filePath":"ru/tools/alerts.md"}'),h={name:"ru/tools/alerts.md"};function c(u,a,p,m,g,b){const o=l("Screenshot");return s(),d("div",null,[a[0]||(a[0]=t("h1",{id:"alerts",tabindex:"-1"},[e("Alerts "),t("a",{class:"header-anchor",href:"#alerts","aria-label":'Permalink to "Alerts"'},"​")],-1)),a[1]||(a[1]=t("p",null,"Alerts следит сразу за двумя вещами и показывает их одной лентой:",-1)),a[2]||(a[2]=t("ol",null,[t("li",null,[t("strong",null,"Расхождения цен"),e(" — один и тот же актив стоит по-разному на разных биржах прямо сейчас.")]),t("li",null,[t("strong",null,"Новые листинги"),e(" — токен, который только что начал торговаться на доступной бирже.")])],-1)),r(o,{src:"alerts",alt:"Окно Alerts с двумя карточками расхождений, одна приглушена, и лентой ликвидаций справа",caption:"Окно Alerts — вторая карточка приглушена; лента ликвидаций пристыкована справа"}),a[3]||(a[3]=i('<h2 id="как-читать-окно" tabindex="-1">Как читать окно <a class="header-anchor" href="#как-читать-окно" aria-label="Permalink to &quot;Как читать окно&quot;">​</a></h2><h3 id="заголовок-окна" tabindex="-1">Заголовок окна <a class="header-anchor" href="#заголовок-окна" aria-label="Permalink to &quot;Заголовок окна&quot;">​</a></h3><p>Заголовок подытоживает действующие настройки: таймфрейм графика, порог <strong>Decorrelation</strong>, <strong>Max Age</strong>, <strong>Max Spread</strong> (если задан) и, когда включён фильтр объёма, <strong>Min 24h Vol</strong>.</p><h3 id="порядок" tabindex="-1">Порядок <a class="header-anchor" href="#порядок" aria-label="Permalink to &quot;Порядок&quot;">​</a></h3><p>Карточки упорядочены от самых новых, по времени, <strong>когда открылся спред</strong>. Карточка держит своё место, пока её числа обновляются, так что лента не перестраивается у вас перед глазами, пока вы её читаете.</p><h3 id="карточка-расхождения" tabindex="-1">Карточка расхождения <a class="header-anchor" href="#карточка-расхождения" aria-label="Permalink to &quot;Карточка расхождения&quot;">​</a></h3><ul><li><strong>Символ</strong> — нажмите, чтобы скопировать в буфер обмена; на миг покажет <code>Copied!</code>.</li><li><strong>Спред</strong> — живой максимальный разрыв цен между биржами в процентах.</li><li><strong>Возраст</strong> — сколько времени спред держится на уровне вашего порога или выше, например <code>12m</code> или <code>3h</code>.</li><li><strong>Легенда</strong> — по одной записи на каждую биржу, где есть этот тикер: цветная точка, соответствующая его линии на графике, название биржи и её объём. Наведение на запись показывает точную цену и объём этой биржи.</li><li><strong>Мини-график</strong> — по одной ценовой линии на биржу, чтобы было видно, расширяется разрыв, сужается или держится.</li><li><strong>Кнопка разворота</strong> — открывает карточку на весь экран; см. <a href="#полноэкранныи-режим">Полноэкранный режим</a>.</li></ul><h4 id="приглушенные-карточки" tabindex="-1">Приглушенные карточки <a class="header-anchor" href="#приглушенные-карточки" aria-label="Permalink to &quot;Приглушенные карточки&quot;">​</a></h4><p>Карточка становится <strong>приглушенной</strong>, когда её живой спред опускается ниже вашего <a href="#minimum-decorrelation">Minimum decorrelation</a>. Спред ещё не завершился — сервер держит его открытым, пока он не пробудет ниже порога <strong>10 минут</strong>. Если разрыв снова расширится, карточка снова подсветится и сохранит свой возраст. Если нет — она исчезнет из ленты.</p><p>Звук оповещения звучит один раз на каждый новый спред, а не повторно, когда приглушенная карточка возвращается.</p><h4 id="как-считается-спред" tabindex="-1">Как считается спред <a class="header-anchor" href="#как-считается-спред" aria-label="Permalink to &quot;Как считается спред&quot;">​</a></h4><p>Процент — это <code>(самая высокая цена − самая низкая цена) ÷ самая низкая цена × 100</code>, взятый по всем биржам, которые сейчас сообщают этот тикер.</p><p>Эта цифра <strong>живая</strong>. Она непрерывно пересчитывается из тех же биржевых вебсокетов, что питают линии графика, и обновляется примерно дважды в секунду — то есть показывает текущий разрыв, а не тот, что был в момент срабатывания оповещения.</p><div class="warning custom-block"><p class="custom-block-title">Спред — не гарантированная прибыль</p><p>Это разница между двумя котировками. Она ничего не говорит о том, смогли бы вы на этом поторговать: глубина стакана, комиссии, фандинг, время перевода и доступность вывода в расчёт не входят, а видимый разрыв может закрыться раньше, чем исполнится ордер. Воспринимайте это как сигнал посмотреть, а не как результат.</p></div><p>График намеренно приближен с плотными ценовыми полями, потому что разрыв между линиями бирж обычно мал относительно цены и в обычном масштабе был бы незаметен.</p><h3 id="полноэкранныи-режим" tabindex="-1">Полноэкранный режим <a class="header-anchor" href="#полноэкранныи-режим" aria-label="Permalink to &quot;Полноэкранный режим&quot;">​</a></h3><p>Кнопка разворота открывает карточку расхождения на всё окно: те же ценовые линии по биржам, легенда, живой спред и его возраст. Выбор таймфрейма работает как в полноэкранном режиме Knives и Monitor, а отмеченные звёздочкой таймфреймы общие с ними. Нажмите <kbd>Esc</kbd> или кнопку закрытия, чтобы выйти.</p><h3 id="карточка-нового-листинга" tabindex="-1">Карточка нового листинга <a class="header-anchor" href="#карточка-нового-листинга" aria-label="Permalink to &quot;Карточка нового листинга&quot;">​</a></h3><p>Карточки листингов выглядят иначе, чем карточки расхождений: тег <strong>NEW</strong>, символ (тоже копируется по клику) и время листинга. Они делят ленту и тот же лимит карточек с оповещениями о расхождениях.</p><h2 id="настроики" tabindex="-1">Настройки <a class="header-anchor" href="#настроики" aria-label="Permalink to &quot;Настройки&quot;">​</a></h2><p>Откройте вкладку <strong>Alerts</strong> в главном окне.</p><h3 id="display" tabindex="-1">Display <a class="header-anchor" href="#display" aria-label="Permalink to &quot;Display&quot;">​</a></h3><h4 id="max-cards" tabindex="-1">Max cards <a class="header-anchor" href="#max-cards" aria-label="Permalink to &quot;Max cards&quot;">​</a></h4><p>Сколько карточек лента показывает одновременно. Диапазон <strong>от 3 до 50</strong>, по умолчанию 9.</p><p>Лимит применяется уже после того, как оповещения о расхождениях и листингах объединены и отсортированы, так что оба типа соревнуются за одни и те же места.</p><h4 id="chart-timeframe" tabindex="-1">Chart timeframe <a class="header-anchor" href="#chart-timeframe" aria-label="Permalink to &quot;Chart timeframe&quot;">​</a></h4><p>Интервал свечей для ценовых линий внутри карточек расхождений. Варианты: <code>1m</code>, <code>5m</code>, <code>15m</code>, <code>30m</code>, <code>1h</code>, <code>4h</code>, <code>1d</code>, <code>1w</code>. По умолчанию <code>1m</code>.</p><p>Это меняет только график. На расчёт спреда и на то, какие оповещения проходят, это не влияет.</p><h3 id="alert-settings" tabindex="-1">Alert settings <a class="header-anchor" href="#alert-settings" aria-label="Permalink to &quot;Alert settings&quot;">​</a></h3><h4 id="minimum-decorrelation" tabindex="-1">Minimum decorrelation <a class="header-anchor" href="#minimum-decorrelation" aria-label="Permalink to &quot;Minimum decorrelation&quot;">​</a></h4><p>Спред, которого тикер должен достичь, чтобы создать оповещение. Диапазон <strong>от 1% до 10%</strong> с шагом 0.5%, по умолчанию 1%.</p><p>Спред, опустившийся ниже этого значения, <a href="#приглушенные-карточки">приглушается</a>, а не исчезает сразу. Он покидает ленту после 10 минут ниже порога.</p><h4 id="max-spread" tabindex="-1">Max spread % <a class="header-anchor" href="#max-spread" aria-label="Permalink to &quot;Max spread %&quot;">​</a></h4><p>Скрывает спреды шире этого значения. По умолчанию <strong>выключено</strong> (пусто). Кнопки − / + меняют значение с шагом 5%, или введите любое число.</p><p>Спред в сотни процентов почти никогда не бывает реальной возможностью. Обычно это две разные монеты под одним тикером на разных биржах. <strong>50%</strong> — хорошая отправная точка.</p><h4 id="max-spread-age" tabindex="-1">Max spread age <a class="header-anchor" href="#max-spread-age" aria-label="Permalink to &quot;Max spread age&quot;">​</a></h4><p>Скрывает спреды, открытые дольше этого времени. Шаги: <strong>Off</strong>, 30m, 1h, 2h, 4h, 8h, 12h, 1d, 2d, 3d, 7d. По умолчанию Off.</p><p>Разрыв, который держится днями, обычно структурный — приостановленный вывод, другой токен, — а не такой, что закроется.</p><h3 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h3><h4 id="alert-sound" tabindex="-1">Alert sound <a class="header-anchor" href="#alert-sound" aria-label="Permalink to &quot;Alert sound&quot;">​</a></h4><p>Воспроизводит звук при появлении нового оповещения о расхождении. По умолчанию включено.</p><h4 id="listing-alert-sound" tabindex="-1">Listing alert sound <a class="header-anchor" href="#listing-alert-sound" aria-label="Permalink to &quot;Listing alert sound&quot;">​</a></h4><p>Воспроизводит звук, когда залистили новый токен. По умолчанию включено.</p><p>Оба независимы — можно оставить листинги со звуком, а расхождения беззвучными, или наоборот.</p><h3 id="volume-filter" tabindex="-1">Volume filter <a class="header-anchor" href="#volume-filter" aria-label="Permalink to &quot;Volume filter&quot;">​</a></h3><h4 id="enable-volume-filter" tabindex="-1">Enable volume filter <a class="header-anchor" href="#enable-volume-filter" aria-label="Permalink to &quot;Enable volume filter&quot;">​</a></h4><p>Фильтрует оповещения о расхождениях по 24-часовому объёму торгов. По умолчанию выключено.</p><div class="info custom-block"><p class="custom-block-title">Нужны двое</p><p>Чтобы оповещение о расхождении прошло фильтр, <strong>хотя бы две биржи</strong> должны превышать минимальный объём. Это сделано намеренно: ценовой разрыв имеет смысл, только если за обеими его сторонами стоят реальные торги.</p></div><p>Этот фильтр действует только на оповещения о расхождениях. Оповещения о новых листингах по объёму не фильтруются — у только что залистенного токена нет значимой истории объёмов.</p><h4 id="minimum-24h-volume" tabindex="-1">Minimum 24h volume <a class="header-anchor" href="#minimum-24h-volume" aria-label="Permalink to &quot;Minimum 24h volume&quot;">​</a></h4><p>24-часовой объём в долларах, нужный бирже, чтобы её сторона расхождения засчитывалась. Введите сумму; по умолчанию <strong>$1 000 000</strong>.</p><p>Неактивен, пока не включён фильтр объёма.</p><div class="info custom-block"><p class="custom-block-title">Все эти фильтры работают на сервере</p><p>Порог, max spread %, max age и фильтр объёма применяются на сервере, так что скрытый спред вообще не доходит до приложения. Изменение значения вступает в силу в течение секунды.</p></div><h2 id="лента-ликвидации" tabindex="-1">Лента ликвидаций <a class="header-anchor" href="#лента-ликвидации" aria-label="Permalink to &quot;Лента ликвидаций&quot;">​</a></h2><p>Alerts может также вести живую ленту <strong>принудительных закрытий позиций</strong> — это отдельный поток от карточек расхождений и листингов, показанный собственной полосой рядом с ними.</p><p>По умолчанию она <strong>включена</strong>. Ликвидации приходят с перпетуалов <strong>Binance</strong> и <strong>Bybit</strong> — бирж, которые их публикуют.</p><h3 id="как-читать-ленту" tabindex="-1">Как читать ленту <a class="header-anchor" href="#как-читать-ленту" aria-label="Permalink to &quot;Как читать ленту&quot;">​</a></h3><p>В заголовке написано <code>LIQUIDATIONS</code>, а рядом, когда что-то приходило недавно, — текущая сумма: <strong>сколько ликвидировано за последние 60 секунд</strong>.</p><p>Каждая строка — одно событие, самые новые сверху:</p><table tabindex="0"><thead><tr><th>Часть</th><th>Значение</th></tr></thead><tbody><tr><td>Время</td><td>Когда произошло</td></tr><tr><td>Цветная точка</td><td>Какая биржа, в её собственном цвете</td></tr><tr><td>Тикер</td><td>Без суффикса <code>USDT</code> / <code>USDC</code></td></tr><tr><td>Сумма</td><td>Номинал именно этой ликвидации</td></tr></tbody></table><p>Полоса на фоне строки масштабируется по размеру, так что крупные события видно, даже не читая цифру. <strong>Клик по строке копирует тикер.</strong></p><p>При наведении событие расписано словами — биржа, <code>long liquidated → forced sell</code> или <code>short liquidated → forced buy</code>, количество и цена.</p><div class="warning custom-block"><p class="custom-block-title">Цвет соответствует давлению, а не слову</p><p>Ликвидированный <strong>лонг</strong> — это принудительная <strong>продажа</strong>; ликвидированный <strong>шорт</strong> — принудительная <strong>покупка</strong>. Лента окрашивает именно по этому результирующему давлению, так же как ромбы ликвидаций в <a href="/manual/ru/customize/majors.html#ликвидации-—-ромбы">слое мажоров</a>.</p></div><p>Пока не пришло первое событие, в ленте написано <code>waiting…</code>, а не пусто.</p><h3 id="как-передвинуть-и-изменить-размер" tabindex="-1">Как передвинуть и изменить размер <a class="header-anchor" href="#как-передвинуть-и-изменить-размер" aria-label="Permalink to &quot;Как передвинуть и изменить размер&quot;">​</a></h3><p><strong>Тяните заголовок <code>LIQUIDATIONS</code></strong>, чтобы пристыковать ленту к любому краю — слева, справа, сверху или снизу. Слева и справа получается колонка строк, сверху и снизу — горизонтальная полоса. По умолчанию справа.</p><p>Чтобы изменить размер, тяните разделитель между лентой и карточками.</p><p>Если сжать окно достаточно сильно, лента спрячется сама, вместо того чтобы вытеснять карточки оповещений.</p><h3 id="настроики-ленты" tabindex="-1">Настройки ленты <a class="header-anchor" href="#настроики-ленты" aria-label="Permalink to &quot;Настройки ленты&quot;">​</a></h3><p>Откройте вкладку <strong>Alerts</strong> в главном окне.</p>',70)),r(o,{src:"liquidations-settings",alt:"Настройки ликвидаций во вкладке Alerts",caption:"Настройки Alerts — ликвидации"}),a[4]||(a[4]=i('<h4 id="enable-liquidation-tape" tabindex="-1">Enable liquidation tape <a class="header-anchor" href="#enable-liquidation-tape" aria-label="Permalink to &quot;Enable liquidation tape&quot;">​</a></h4><p>Показывает принудительные закрытия позиций в реальном времени. <strong>Включено по умолчанию.</strong> Пока это выключено, всё ниже не действует.</p><h4 id="minimum-size" tabindex="-1">Minimum size <a class="header-anchor" href="#minimum-size" aria-label="Permalink to &quot;Minimum size&quot;">​</a></h4><p>Размер одной ликвидации в долларах. Диапазон <strong>от $5 000 до $1 000 000</strong> с шагом $5 000, по умолчанию $50 000. Действует на каждую биржу, у которой нет собственного размера.</p><p>$5 000 — собственный порог сервера: меньшего он не хранит, так что минимальное значение уже означает «вообще всё, что есть».</p><h4 id="настроики-по-биржам" tabindex="-1">Настройки по биржам <a class="header-anchor" href="#настроики-по-биржам" aria-label="Permalink to &quot;Настройки по биржам&quot;">​</a></h4><p>Под минимальным размером есть отдельный блок для <strong>Binance</strong> и для <strong>Bybit</strong>:</p><ul><li>Переключатель, чтобы полностью заглушить эту биржу.</li><li><strong>Size on this venue</strong> — собственный минимальный размер биржи. В крайнем левом положении показывает <code>global $50K</code> и следует за минимальным размером выше.</li></ul><p>$50K — обычное дело на Binance, но может быть крупным событием в другом месте, так что собственный размер для каждой биржи не даёт одной бирже заглушить другую. Если заглушены обе, приложение предупреждает, что ничего не придёт.</p><h4 id="minimum-24h-turnover" tabindex="-1">Minimum 24h turnover <a class="header-anchor" href="#minimum-24h-turnover" aria-label="Permalink to &quot;Minimum 24h turnover&quot;">​</a></h4><p>Скрывает тонкие тикеры по их обороту за 24 часа. Диапазон <strong>от $0 до $50M</strong> с шагом $1M, по умолчанию 0 — показывается как <code>off</code>, то есть без фильтрации.</p><div class="warning custom-block"><p class="custom-block-title">Ненулевое значение скрывает и неизвестные тикеры</p><p>Любой тикер, чей оборот за 24 часа ещё неизвестен, тоже будет скрыт — не только действительно тонкие. В только что открытом окне это может означать заметно меньше событий, пока данные об обороте не придут.</p></div><h4 id="blacklist" tabindex="-1">Blacklist <a class="header-anchor" href="#blacklist" aria-label="Permalink to &quot;Blacklist&quot;">​</a></h4><p>Тикеры, которые никогда не показывать. Введите тикер и нажмите <kbd>Enter</kbd>, чтобы добавить; <strong>Clear all</strong> очищает список.</p><p>Полезно для тех нескольких тикеров, которые ликвидируются постоянно и иначе заполонили бы всю ленту.</p><h4 id="rows-kept" tabindex="-1">Rows kept <a class="header-anchor" href="#rows-kept" aria-label="Permalink to &quot;Rows kept&quot;">​</a></h4><p>Сколько событий держит лента, прежде чем удалять самые старые. Диапазон <strong>от 20 до 300</strong> с шагом 20, по умолчанию 100.</p><h4 id="liquidation-sound" tabindex="-1">Liquidation sound <a class="header-anchor" href="#liquidation-sound" aria-label="Permalink to &quot;Liquidation sound&quot;">​</a></h4><p>Воспроизводит звук при поступлении ликвидации. <strong>Выключено по умолчанию.</strong></p><p>Учтите: он срабатывает на <em>каждое</em> событие, прошедшее ваши фильтры, — при низком минимальном размере на активном рынке это очень много звука. Сначала поднимите <strong>Minimum size</strong>, и только потом включайте.</p><h2 id="связанное" tabindex="-1">Связанное <a class="header-anchor" href="#связанное" aria-label="Permalink to &quot;Связанное&quot;">​</a></h2><ul><li><a href="/manual/ru/tools/knives.html">Knives</a> — движения цен на одной бирже вместо разрывов между биржами. Knives также показывает значок <strong>NEW</strong> для свежих листингов на своих карточках тикеров.</li><li><a href="/manual/ru/tools/monitor.html">Monitor</a> — ранжированный обзор рынка</li><li><a href="/manual/ru/tools/ticks.html">Ticks</a> — крупные сделки по мере печати</li></ul>',22))])}const k=n(h,[["render",c]]);export{f as __pageData,k as default};
